/**
 * Ingest NotebookLM Generated Human Biology Slide Decks
 *
 * Extracts slides from PPTX files generated by the NotebookLM agent,
 * binds them to the "intro_aaq_human_bio" slide set,
 * and sets up interactive starter activity grids and diagnostic questions.
 */

import fs from "node:fs/promises";
import path from "node:path";
import { extractPptxDeck } from "../src/pptx-extractor.js";
import { lessons } from "../src/configs/intro_aaq_human_bio.js";

const NOTEBOOK_OUTPUT_DIR = "/Users/danieltagg/Desktop/Desktop - Daniel’s MacBook Pro/NotebookLMagent/output/powerpoints_aaq_human_bio";
const PUBLIC_DECKS_DIR = path.resolve("./public/decks");

export async function ingestAllHumanBioDecks() {
  console.log(`[Ingest Human Bio] Checking directory: ${NOTEBOOK_OUTPUT_DIR}`);
  
  const dirStat = await fs.stat(NOTEBOOK_OUTPUT_DIR).catch(() => null);
  if (!dirStat || !dirStat.isDirectory()) {
    console.log(`[Ingest Human Bio] Output directory does not exist yet: ${NOTEBOOK_OUTPUT_DIR}`);
    return [];
  }

  const files = await fs.readdir(NOTEBOOK_OUTPUT_DIR);
  const pptxFiles = files.filter(f => f.startsWith("Lesson_") && f.endsWith(".pptx") && !f.startsWith("~$"));
  console.log(`[Ingest Human Bio] Found ${pptxFiles.length} PPTX deck(s) in output directory.`);

  const ingestedDecks = [];

  for (const file of pptxFiles) {
    const fullPath = path.join(NOTEBOOK_OUTPUT_DIR, file);
    const baseId = path.basename(file, ".pptx");
    
    // Match to lesson config
    const lessonMatch = baseId.match(/Lesson_0?(\d+)/i);
    const lessonNum = lessonMatch ? parseInt(lessonMatch[1], 10) : null;
    const lessonConfig = lessonNum ? lessons.find(l => l.number === lessonNum) : null;

    const targetDeckId = lessonConfig?.deckId || baseId;
    console.log(`[Ingest Human Bio] Ingesting: ${file} -> ${targetDeckId} (Lesson ${lessonNum || "unknown"})`);

    const manifest = await extractPptxDeck(fullPath, PUBLIC_DECKS_DIR, targetDeckId, {
      slideSet: "intro_aaq_human_bio",
      title: lessonConfig?.title || baseId.replace(/^Lesson_\d+_?/, "").replace(/_/g, " ")
    });

    // Enrich manifest with lesson metadata & starter grid if available
    if (lessonConfig && manifest.slides && manifest.slides.length >= 2) {
      // Mark slide 2 as interactive starter if starterQuestions exist
      if (lessonConfig.starterQuestions && lessonConfig.starterQuestions.length > 0) {
        manifest.slides[1].isInteractive = true;
        manifest.slides[1].interactiveType = "six_cell_grid";
        manifest.slides[1].starterQuestions = lessonConfig.starterQuestions;
        manifest.slides[1].title = `Starter Activity: 6-Cell Knowledge Retrieval`;

        const cellBounds = [
          { row: 0, col: 0, bounds: { x: 6.8, y: 30.5, w: 41.5, h: 22.0 } },
          { row: 0, col: 1, bounds: { x: 51.5, y: 30.5, w: 41.5, h: 22.0 } },
          { row: 1, col: 0, bounds: { x: 6.8, y: 55.0, w: 41.5, h: 22.0 } },
          { row: 1, col: 1, bounds: { x: 51.5, y: 55.0, w: 41.5, h: 22.0 } },
          { row: 2, col: 0, bounds: { x: 6.8, y: 78.5, w: 41.5, h: 18.5 } },
          { row: 2, col: 1, bounds: { x: 51.5, y: 78.5, w: 41.5, h: 18.5 } }
        ];

        manifest.slides[1].interactiveCells = lessonConfig.starterQuestions.slice(0, 6).map((qObj, idx) => ({
          id: `cell_${idx + 1}`,
          row: cellBounds[idx].row,
          col: cellBounds[idx].col,
          bounds: cellBounds[idx].bounds,
          question: qObj.q,
          expectedAnswer: qObj.a,
          answer: qObj.a,
          overlayAnswer: true,
          revealMode: "overlay",
          confidence: 1
        }));
        manifest.slides[1].cells = manifest.slides[1].interactiveCells;
      }

      manifest.lessonNumber = lessonConfig.number;
      manifest.courseName = "OCR Level 3 Cambridge Advanced National (AAQ) in Human Biology";
      manifest.teacher = lessonConfig.teacher || "Dan";
      manifest.objectives = lessonConfig.objectives || null;
      manifest.terminology = lessonConfig.terminology || null;

      const manifestPath = path.join(PUBLIC_DECKS_DIR, targetDeckId, "manifest.json");
      await fs.writeFile(manifestPath, JSON.stringify(manifest, null, 2), "utf8");
    }

    ingestedDecks.push(manifest);
    console.log(`[Ingest Human Bio] Successfully ingested ${baseId} (${manifest.slides?.length || 0} slides)`);
  }

  return ingestedDecks;
}

if (process.argv[1]?.endsWith("ingest-human-bio-decks.mjs")) {
  ingestAllHumanBioDecks().catch(err => {
    console.error("[Ingest Human Bio] Error:", err);
    process.exit(1);
  });
}
